<?php defined('BASEPATH') or exit('No direct script access allowed');$operationLabels=['contracts'=>'Contratos','tickets'=>'Chamados','projects'=>'Projetos'];$operationStates=['draft'=>'Rascunho','active'=>'Ativo','cancelled'=>'Cancelado','open'=>'Aberto','resolved'=>'Resolvido','closed'=>'Encerrado','completed'=>'Concluído'];$operationFileForms=function(string $kind,array $record)use($url,$hidden,$esc){foreach($record['files']??[] as $file){echo form_open($url);$hidden('operation_file'); ?><input type="hidden" name="operation_kind" value="<?= $esc($kind); ?>"><input type="hidden" name="resource_id" value="<?= (int)$record['id']; ?>"><input type="hidden" name="file_key" value="<?= $esc($file['file_key']); ?>"><button type="submit">Baixar anexo: <?= $esc($file['filename']); ?></button><?= form_close(); ?><?php }}; ?>
<?php if($operation_detail??null){ ?><section id="portal-operation-detail"><h2><?= $esc($operationLabels[$operation_kind]); ?> — <?= $esc($operation_detail['name']); ?></h2><p><?= $esc($operationStates[$operation_detail['status']]??'Consultar empresa'); ?></p><?php if(isset($operation_detail['start_date'])){ ?><p>Vigência: <?= $esc($operation_detail['start_date'].' até '.$operation_detail['due_date']); ?></p><?php } ?><div style="white-space:pre-wrap"><?= $esc($operation_detail['body']??$operation_detail['description']??''); ?></div>
<?php if($operation_kind==='tickets'){ ?><h3>Mensagens publicadas pela empresa</h3><?php foreach($operation_detail['replies'] as $reply){ ?><article><p style="white-space:pre-wrap"><?= $esc($reply['body']); ?></p><small><?= $esc($reply['created_at']); ?></small></article><?php } ?><?php } ?>
<?php if($operation_kind==='contracts'){ ?><?= form_open($url);$hidden('operation_contract_pdf'); ?><input type="hidden" name="resource_id" value="<?= (int)$operation_detail['id']; ?>"><button type="submit">Baixar PDF do contrato</button><?= form_close(); ?><p>Documento de registro. A disponibilização no portal não representa assinatura ou aceite eletrônico.</p><?php }$operationFileForms($operation_kind,$operation_detail); ?><a href="<?= $esc($url); ?>">Voltar às listas</a></section><?php } ?>
<?php foreach($operations??[] as $kind=>$page){if(!is_array($page))continue; ?><section id="portal-<?= $esc($kind); ?>"><h2><?= $esc($operationLabels[$kind]); ?> desta empresa</h2><p>Somente registros publicados para seu cadastro, com permissão específica. Documentos, mensagens e anexos internos não publicados permanecem privados.</p><?php foreach($page['items'] as $record){ ?><article><h3><a href="<?= $esc($url.'?operation_kind='.$kind.'&resource_id='.(int)$record['id']); ?>"><?= $esc($record['name']); ?></a></h3><p><?= $esc($operationStates[$record['status']]??'Consultar empresa'); ?></p><?php $operationFileForms($kind,$record); ?></article><?php }if(!$page['items']){ ?><p>Nenhum registro publicado disponível.</p><?php }if($page['next']!==null){ ?><a href="<?= $esc($url.'?op_after_'.$kind.'='.(int)$page['next']); ?>">Próxima página de <?= $esc(mb_strtolower($operationLabels[$kind])); ?></a><?php } ?></section><?php } ?>
